// Builds the main window's page: index.html from index.src.html, with its 29 scripts and 9 stylesheets
// joined into ui.bundle.js and ui.bundle.css. The Settings page gets the same: settings.html from settings.src.html, joined into
// settings.bundle.js and settings.bundle.css (it took 180 ms to load 16 scripts and 5 stylesheets one by one). One file each loads far faster than thirty-eight from disk
// (about 100 ms off the window's first tab showing), and the script runs deferred, after the markup has painted.
// The output is committed; test/units/units.js checks it still matches this script's output.
// Edit index.src.html and the files it lists, then run:  node scripts/build/bundle-renderer.js
const fs = require('fs');
const path = require('path');
const acorn = require('acorn'); // a dev dependency (eslint brings it); only this build step uses it

const DIR = path.join(__dirname, '..', '..', 'src', 'renderer');
const read = (file) => fs.readFileSync(path.join(DIR, file), 'utf8').replace(/\r\n/g, '\n');
const SCRIPT = /[ \t]*<script src="([^"]+)"><\/script>(?:<!--.*?-->)?[ \t]*\n?/g;
const STYLE = /[ \t]*<link rel="stylesheet" href="([^"]+)" \/>(?:<!--.*?-->)?[ \t]*\n?/g;

// The stylesheets' comments are left out of ui.bundle.css and settings.bundle.css (about 30 KB the window would load and parse on every start; the
// source files keep them). A string is copied as it is, so a "/*" inside content: "…" or a url("…") is never taken for a comment.
function stripCssComments(css) {
  let out = '';
  for (let i = 0; i < css.length; i++) {
    const c = css[i];
    if (c === '"' || c === "'") { const end = css.indexOf(c, i + 1); const stop = end === -1 ? css.length : end + 1; out += css.slice(i, stop); i = stop - 1; continue; }
    if (c === '/' && css[i + 1] === '*') { const end = css.indexOf('*/', i + 2); i = end === -1 ? css.length : end + 1; continue; }
    out += c;
  }
  // (indentation and blank lines go too: CSS has no line numbers to keep, unlike the scripts below)
  return out.replace(/[ \t]+\n/g, '\n').replace(/^[ \t]+/gm, '').replace(/\n{2,}/g, '\n');
}

// The scripts' comments are left out of ui.bundle.js and settings.bundle.js too (the source is comment-heavy: about 190 KB the window would
// download, parse and hold on every start). acorn finds the comments, so "//" or "/*" inside a string, a regex or a template literal is never
// touched. Line structure is kept (a removed comment leaves its newlines, so line numbers inside each file, after its "// ---- name" marker,
// still count the same as in the source), and /*! ... */ and @license / @preserve comments stay. The source files keep every comment.
function stripJsComments(code, name = 'script') {
  const comments = [];
  try {
    acorn.parse(code, { ecmaVersion: 'latest', sourceType: 'script', allowHashBang: true, onComment: (block, text, start, end) => comments.push({ block, text, start, end }) });
  } catch (e) {
    throw new Error('bundle-renderer: cannot parse ' + name + ' to strip its comments: ' + e.message);
  }
  let out = '';
  let at = 0;
  const blank = (ch) => ch === undefined || ch === ' ' || ch === '\t' || ch === '\n';
  for (const c of comments) {
    if (c.block && (c.text.startsWith('!') || /@license|@preserve/.test(c.text))) continue;
    const nl = c.block ? (code.slice(c.start, c.end).match(/\n/g) || []).length : 0;
    const endsLine = code[c.end] === '\n' || code[c.end] === undefined;
    // drop the blanks before a comment that ends its line (or breaks one), so no trailing spaces are left behind
    let from = c.start;
    if (!c.block || nl || endsLine) while (from > at && (code[from - 1] === ' ' || code[from - 1] === '\t')) from--;
    out += code.slice(at, from);
    if (c.block) {
      // spanning lines it is a line break to ASI, so keep the breaks; on one line it separates tokens (a/**/b), so keep a space unless a blank or a line end already does
      out += nl ? '\n'.repeat(nl) : (blank(code[c.start - 1]) || blank(code[c.end]) ? '' : ' ');
    }
    at = c.end;
  }
  return out + code.slice(at);
}

// `page` is 'index' (-> ui.bundle.*) or 'settings' (-> settings.bundle.*)
function bundle(page = 'index') {
  const base = page === 'index' ? 'ui' : page;
  const src = read(`${page}.src.html`);
  const scripts = [...src.matchAll(SCRIPT)].map((m) => m[1]);
  const styles = [...src.matchAll(STYLE)].map((m) => m[1]);
  const js = [
    '// Generated by scripts/build/bundle-renderer.js from index.src.html. Do not edit; edit the files it lists and rerun it.',
    ...scripts.map((s) => `// ---- ${s}\n${stripJsComments(read(s), s).trimEnd()}\n;`),
    '',
  ].join('\n');
  const css = [
    '/* Generated by scripts/build/bundle-renderer.js from index.src.html. Do not edit; edit the files it lists and rerun it. */',
    ...styles.map((s) => `/* ---- ${s} */\n${stripCssComments(read(s)).trim()}`),
    '',
  ].join('\n');
  let nScript = 0;
  let nStyle = 0;
  const html = src
    .replace(SCRIPT, () => (nScript++ ? '' : `  <script src="${base}.bundle.js" defer></script>\n`))
    .replace(STYLE, () => (nStyle++ ? '' : `  <link rel="stylesheet" href="${base}.bundle.css" />\n`));
  return { html, js, css, scripts, styles, base };
}

if (require.main === module) {
  for (const page of ['index', 'settings']) {
    const out = bundle(page);
    fs.writeFileSync(path.join(DIR, `${page}.html`), out.html);
    fs.writeFileSync(path.join(DIR, `${out.base}.bundle.js`), out.js);
    fs.writeFileSync(path.join(DIR, `${out.base}.bundle.css`), out.css);
    console.log(`wrote ${page}.html, ${out.base}.bundle.js (${out.scripts.length} scripts), ${out.base}.bundle.css (${out.styles.length} stylesheets)`);
  }
}
module.exports = { bundle, stripJsComments, stripCssComments };
